      pt: ["Estabelecido em 1620.", "Ashina Yoshikatsu era o senhor local.", "Localização na província de Akita.", "Frequentemente chamada de Pequena Quioto de Michinoku.", "Muitas casas de samurais estão abertas a visitantes.", "Famoso pelas Shidarezakura na primavera.", "Ruas largas e cercas de madeira escura marcam o bairro."],
      fr: ["Aménagé en 1620.", "Ashina Yoshikatsu était le seigneur local.", "Situé dans la préfecture d'Akita.", "Souvent surnommé la Petite Kyoto de Michinoku.", "De nombreuses maisons de samouraïs sont ouvertes aux visiteurs.", "Célèbre pour ses Shidarezakura au printemps.", "Des rues larges et des clôtures en bois sombre caractérisent le quartier."],
